use vstd::prelude::*;

verus! {

spec fn rev_index(i: nat, n: nat) -> nat {
    // index in the original array corresponding to i in the reversed array
    (n - 1 - i)
}

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int|
            0 <= i < result.len() ==> result[i] == m[(m.len() - 1 - i) as int],
{
    let n = m.len();
    let mut result = Vec::with_capacity(n);

    for &x in m.iter().rev()
        invariant
            result.len() <= n,
            // result is always a prefix of the reverse of m
            forall|i: int|
                0 <= i < result.len() ==> result[i] == m[(n - 1 - i) as int],
        decreases n - result.len(),
    {
        result.push(x);
    }

    result
}

}

